import functools
import pytest
from fastapi import FastAPI, Depends
from fastapi.testclient import TestClient
from typing import Annotated

def test_partial_dependency():
    app = FastAPI()

    def dep_func(x: int, y: int):
        return x + y

    partial_dep = functools.partial(dep_func, x=1)

    @app.get("/")
    async def root(val: Annotated[int, Depends(partial_dep)]):
        return {"val": val}

    client = TestClient(app)
    response = client.get("/?y=2")
    assert response.status_code == 200
    assert response.json() == {"val": 3}

async def async_dep_func(x: int, y: int):
    return x + y

def test_partial_async_dependency():
    app = FastAPI()

    partial_dep = functools.partial(async_dep_func, x=10)

    @app.get("/")
    async def root(val: Annotated[int, Depends(partial_dep)]):
        return {"val": val}

    client = TestClient(app)
    response = client.get("/?y=5")
    assert response.status_code == 200
    assert response.json() == {"val": 15}

class CallClass:
    def __call__(self, x: int, y: int):
        return x + y

def test_partial_class_dependency():
    app = FastAPI()

    call_instance = CallClass()
    partial_dep = functools.partial(call_instance, x=100)

    @app.get("/")
    async def root(val: Annotated[int, Depends(partial_dep)]):
        return {"val": val}

    client = TestClient(app)
    response = client.get("/?y=200")
    assert response.status_code == 200
    assert response.json() == {"val": 300}
